const inp = $input.first().json;
const s = $('Chuẩn hóa dữ liệu').first().json;
if (!inp.candidates || !inp.candidates[0] || !inp.candidates[0].content) {
  return [{json:{report_id:s.report_id,title:s.title,description:s.description,image_url:s.image_url,tinh_trang:'Loi AI',muc_do:'khong xac dinh',ten_benh:'Khong co',khuyen_nghi:'Loi: '+JSON.stringify(inp).substring(0,200),ai_full:JSON.stringify(inp).substring(0,500)}}];
}
const t = inp.candidates[0].content.parts[0].text;
const tt = (t.match(/TINH_TRANG:\s*(.+?)(?=\n|$)/)||[])[1]||'Khong xac dinh';
const md = (t.match(/MUC_DO:\s*(.+?)(?=\n|$)/)||[])[1]||'Khong xac dinh';
const tb = (t.match(/TEN_BENH:\s*(.+?)(?=\n|$)/)||[])[1]||'Khong co';
const kn = (t.match(/KHUYEN_NGHI:\s*(.+?)(?=\n|$)/)||[])[1]||'';
return [{json:{report_id:s.report_id,title:s.title,description:s.description,image_url:s.image_url,tinh_trang:tt.trim(),muc_do:md.trim().toLowerCase(),ten_benh:tb.trim(),khuyen_nghi:kn.trim(),ai_full:t}}];

